/* src/host/Chat/dynamic-island/DynamicIsland.css */
.island-root {
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  z-index: var(--z-float, 30);
  width: fit-content;
  min-width: 220px;
  max-width: min(440px, calc(100% - 32px));
  border-radius: 0 0 14px 14px;
  background: rgba(var(--c-bg-surface), 0.72);
  border: none;
  box-shadow:
    0 10px 30px rgba(0, 0, 0, 0.5),
    inset 0 1px 0 rgba(255, 255, 255, 0.05),
    inset 0 -8px 24px var(--island-aura, transparent);
  backdrop-filter: blur(14px) saturate(1.5);
  -webkit-backdrop-filter: blur(14px) saturate(1.5);
  will-change: transform;
  overflow: hidden;
  transition: border-radius 0.42s cubic-bezier(0.34, 1.56, 0.64, 1), width 0.45s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.island-root::before {
  content: "";
  position: absolute;
  left: 16%;
  right: 16%;
  bottom: -1px;
  height: 2px;
  border-radius: 2px;
  background:
    linear-gradient(
      90deg,
      transparent,
      var(--island-glow, rgb(var(--c-text-muted))),
      transparent);
  opacity: 0.5;
  transition: opacity 0.3s ease, background 0.3s ease;
  pointer-events: none;
}
.island-root:hover::before {
  opacity: 0.85;
}
.island-root.island-expanded {
  border-radius: 0 0 18px 18px;
  width: min(440px, calc(100% - 32px));
}
.island-root.is-ready,
.island-root.is-resident {
  --island-glow: rgb(var(--c-primary));
  --island-aura: rgba(var(--c-primary), 0.05);
}
.island-root.is-running {
  --island-glow: rgb(var(--c-status-info));
  --island-aura: rgba(var(--c-status-info), 0.08);
}
.island-root.is-thinking {
  --island-glow: rgb(var(--c-accent-ai));
  --island-aura: rgba(var(--c-accent-ai), 0.08);
}
.island-root.is-thinking {
  background: rgba(var(--c-bg-surface), 0.92);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}
.island-root.is-urgent {
  --island-glow: rgb(var(--c-status-warning));
  --island-aura: rgba(var(--c-status-warning), 0.08);
}
.island-root.is-interrupt {
  --island-glow: rgb(var(--c-text-muted));
  --island-aura: rgba(var(--c-text-muted), 0.05);
}
.island-root.is-done {
  --island-glow: rgb(var(--c-primary));
  --island-aura: rgba(var(--c-primary), 0.05);
}
.island-root.is-fail {
  --island-glow: rgb(var(--c-status-danger));
  --island-aura: rgba(var(--c-status-danger), 0.08);
}
.island-compact {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 30px;
  padding: 0 12px;
  cursor: pointer;
  user-select: none;
}
.island-collapsed .island-compact {
  height: 26px;
}
.island-sym {
  position: relative;
  width: 14px;
  height: 14px;
  flex-shrink: 0;
  will-change: transform;
  display: grid;
  place-items: center;
}
.island-sym .island-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--island-glow, rgb(var(--c-status-info)));
  box-shadow: 0 0 8px var(--island-glow, rgb(var(--c-status-info)));
}
.island-collapsed .island-sym .island-dot {
  width: 6px;
  height: 6px;
}
.island-sym .island-wave {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 1.5px solid var(--island-glow, rgb(var(--c-status-info)));
  opacity: 0;
  will-change: transform;
}
.is-running .island-sym .island-wave,
.is-thinking .island-sym .island-wave,
.is-urgent .island-sym .island-wave,
.is-interrupt .island-sym .island-wave {
  animation: island-wave 1.8s ease-out infinite;
}
.is-urgent .island-sym .island-wave {
  animation-duration: 1.1s;
}
.is-thinking .island-sym .island-wave {
  animation-duration: 2.4s;
}
.is-running .island-sym .island-dot {
  animation: island-breathe 1.6s ease-in-out infinite;
}
.is-thinking .island-sym .island-dot {
  animation: island-breathe 2.8s ease-in-out infinite;
}
.is-urgent .island-sym .island-dot {
  animation: island-blink 0.7s steps(2) infinite;
}
@keyframes island-wave {
  0% {
    transform: scale(0.5);
    opacity: 0.7;
  }
  100% {
    transform: scale(1.8);
    opacity: 0;
  }
}
@keyframes island-breathe {
  0%, 100% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.35);
  }
}
@keyframes island-blink {
  0%, 49% {
    opacity: 1;
  }
  50%, 100% {
    opacity: 0.3;
  }
}
.island-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
  position: relative;
  background: var(--island-glow, rgb(var(--c-status-info)));
}
.island-main {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
}
.island-carousel {
  position: relative;
  flex: 1;
  min-width: 0;
  height: 16px;
  overflow: hidden;
}
.island-slide {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  gap: 6px;
  opacity: 0;
  transform: translateY(4px);
  transition: opacity 0.35s, transform 0.35s;
  pointer-events: none;
  white-space: nowrap;
  overflow: hidden;
}
.island-slide-on {
  opacity: 1;
  transform: translateY(0);
  pointer-events: auto;
}
.island-seg {
  display: flex;
  align-items: center;
  gap: 5px;
  white-space: nowrap;
  overflow: hidden;
  min-width: 0;
}
.island-seg-ico {
  width: 13px;
  height: 13px;
  flex-shrink: 0;
  color: rgb(var(--c-text-secondary));
  display: flex;
  align-items: center;
  justify-content: center;
}
.island-seg-ico > svg {
  width: 100%;
  height: 100%;
}
.island-seg-lbl {
  color: rgb(var(--c-text-secondary));
}
.island-seg-val {
  color: rgb(var(--c-text-primary));
  font-weight: 500;
}
.island-seg-active {
  color: rgb(var(--c-primary));
}
.island-mini-bar {
  width: 32px;
  height: 3px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 2px;
  overflow: hidden;
  flex-shrink: 0;
}
.island-mini-bar > i {
  display: block;
  height: 100%;
  background: rgb(var(--c-primary));
  border-radius: 2px;
}
.island-muted {
  color: rgb(var(--c-text-tertiary));
}
.island-time {
  color: rgb(var(--c-text-tertiary));
  font-size: 11px;
  flex-shrink: 0;
  font-variant-numeric: tabular-nums;
}
.island-collapsed .island-time {
  color: rgb(var(--c-status-success));
}
.island-chev {
  color: rgb(var(--c-text-muted));
  flex-shrink: 0;
  display: flex;
  align-items: center;
  transition: transform 0.25s;
}
.island-chev > svg {
  width: 11px;
  height: 11px;
}
.island-expanded .island-chev {
  transform: rotate(180deg);
}
.island-interrupt {
  display: flex;
  align-items: center;
  gap: 6px;
  color: rgb(var(--c-text-secondary));
}
.island-interrupt-ico {
  color: rgb(var(--c-status-warning));
  display: flex;
}
.island-panel {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.32s cubic-bezier(0.4, 0, 0.2, 1);
  display: flex;
  flex-direction: column;
}
.island-expanded .island-panel {
  max-height: min(540px, 70vh);
}
.island-panel-inner {
  padding: 0 8px 10px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  overflow-y: auto;
  flex: 1 1 auto;
  min-height: 0;
  scrollbar-width: thin;
}
.island-panel-inner::-webkit-scrollbar {
  width: 6px;
}
.island-panel-inner::-webkit-scrollbar-thumb {
  background: rgba(var(--c-border), 0.25);
  border-radius: 3px;
}
.island-panel-inner::-webkit-scrollbar-track {
  background: transparent;
}
.island-panel-head {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 8px 2px;
}
.island-panel-title {
  flex: 1;
  font-size: 11px;
  color: rgb(var(--c-text-tertiary));
  font-weight: 500;
  letter-spacing: 0.03em;
}
.island-panel-time {
  font-size: 10px;
  color: rgb(var(--c-text-tertiary));
  font-variant-numeric: tabular-nums;
}
.island-close {
  width: 18px;
  height: 18px;
  border: none;
  border-radius: 5px;
  background: transparent;
  color: rgb(var(--c-text-tertiary));
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  transition: background 0.12s ease-out, color 0.12s ease-out;
}
.island-close:hover {
  background: rgba(255, 255, 255, 0.08);
  color: rgb(var(--c-text-primary));
}
.island-close > svg {
  width: 11px;
  height: 11px;
}
.island-sec-head {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 8px 2px;
  font-size: 10px;
  color: rgb(var(--c-text-muted));
  letter-spacing: 0.03em;
  text-transform: uppercase;
}
.island-sec-head-ico {
  display: flex;
}
.island-sec-head-ico > svg {
  width: 11px;
  height: 11px;
}
.island-sec-head .island-sec-head-count {
  margin-left: auto;
  font-variant-numeric: tabular-nums;
}
.island-card {
  border: 1px solid rgba(var(--c-border), 0.07);
  border-radius: 8px;
  padding: 7px 10px;
  background: rgba(var(--c-bg-surface), 0.4);
}
.island-card .r-top {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 4px;
}
.island-card .r-ico {
  width: 14px;
  height: 14px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}
.island-card .r-ico > svg {
  width: 100%;
  height: 100%;
}
.island-card .r-title {
  font-size: 12px;
  font-weight: 500;
  color: rgb(var(--c-text-primary));
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.island-card .r-meta {
  font-size: 10px;
  color: rgb(var(--c-text-tertiary));
  flex-shrink: 0;
  font-variant-numeric: tabular-nums;
}
.island-card .r-bar {
  height: 3px;
  background: rgba(255, 255, 255, 0.08);
  border-radius: 2px;
  overflow: hidden;
  margin: 4px 0 3px;
}
.island-card .r-bar > i {
  display: block;
  height: 100%;
  border-radius: 2px;
  background: rgb(var(--c-primary));
  transition: width 0.4s;
}
.island-card .r-detail {
  font-size: 11px;
  color: rgb(var(--c-text-secondary));
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.island-card .r-ico-task {
  color: rgb(var(--c-primary));
}
.island-card .r-ico-agent {
  color: rgb(var(--c-accent-ai));
}
.island-card .r-ico-workflow {
  color: rgb(var(--c-primary));
}
.island-card .r-ico-tool {
  color: rgb(var(--c-text-secondary));
}
.island-card .r-ico-plan {
  color: rgb(var(--c-primary));
}
.island-card .r-ico-progress {
  color: rgb(var(--c-text-tertiary));
}
.island-urgent {
  border: 1px solid rgba(var(--c-status-warning), 0.35);
  background: rgba(var(--c-status-warning), 0.08);
  padding: 8px 10px;
}
.island-urgent .u-top {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 4px;
}
.island-urgent .u-ico {
  width: 16px;
  height: 16px;
  color: rgb(var(--c-status-warning));
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}
.island-urgent .u-ico > svg {
  width: 100%;
  height: 100%;
}
.island-urgent .u-title {
  font-size: 12px;
  font-weight: 500;
  color: rgb(var(--c-text-primary));
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.island-urgent .u-count {
  font-size: 10px;
  color: rgb(var(--c-status-warning));
  flex-shrink: 0;
  font-variant-numeric: tabular-nums;
}
.island-urgent .u-desc {
  font-size: 11px;
  color: rgb(var(--c-text-secondary));
  line-height: 1.5;
  margin-bottom: 6px;
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}
.island-urgent .u-actions {
  display: flex;
  gap: 6px;
}
.island-btn {
  font-size: 11px;
  padding: 3px 10px;
  border-radius: 6px;
  border: 1px solid rgba(var(--c-border), 0.12);
  background: transparent;
  color: rgb(var(--c-text-secondary));
  cursor: pointer;
  transition: background 0.12s ease-out, color 0.12s ease-out;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.island-btn:hover {
  background: rgba(255, 255, 255, 0.06);
  color: rgb(var(--c-text-primary));
}
.island-btn > svg {
  width: 11px;
  height: 11px;
}
.island-btn-primary {
  background: rgb(var(--c-primary));
  border-color: rgb(var(--c-primary));
  color: rgb(var(--c-on-primary));
}
.island-btn-primary:hover {
  background: rgb(var(--c-status-info));
  color: rgb(var(--c-on-primary));
}
.island-btn-danger {
  color: rgb(var(--c-status-danger));
  border-color: rgba(var(--c-status-danger), 0.3);
}
.island-btn-danger:hover {
  background: rgba(var(--c-status-danger), 0.1);
  color: rgb(var(--c-status-danger));
}
.island-fail {
  border-color: rgba(var(--c-status-danger), 0.3);
  background: rgba(var(--c-status-danger), 0.06);
}
.island-fail .r-detail {
  color: rgb(var(--c-status-danger));
}
.island-fail .r-ico {
  color: rgb(var(--c-status-danger));
}
.island-task-list {
  display: flex;
  flex-direction: column;
  gap: 1px;
  margin-top: 4px;
}
.island-task-row {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 2px 4px;
  border-radius: 4px;
}
.island-task-row:hover {
  background: rgba(255, 255, 255, 0.03);
}
.island-task-row .t-dot {
  width: 12px;
  height: 12px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}
.island-task-row .t-dot > svg {
  width: 12px;
  height: 12px;
}
.island-task-row .t-dot-done {
  color: rgb(var(--c-status-success));
}
.island-task-row .t-dot-active {
  color: rgb(var(--c-primary));
}
.island-task-row .t-dot-pending {
  color: rgb(var(--c-text-muted));
}
.island-task-row .t-dot-blocked {
  color: rgb(var(--c-status-danger));
}
.island-task-row .t-txt {
  font-size: 11px;
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.island-task-row .t-txt-done {
  color: rgb(var(--c-text-muted));
  text-decoration: line-through;
}
.island-task-row .t-txt-active {
  color: rgb(var(--c-primary));
}
.island-task-row .t-txt-pending {
  color: rgb(var(--c-text-secondary));
}
.island-task-row .t-txt-blocked {
  color: rgb(var(--c-status-danger));
}
.island-task-row .t-num {
  font-size: 10px;
  color: rgb(var(--c-text-muted));
  font-family: var(--c-font-mono, "SF Mono", "JetBrains Mono", Consolas, monospace);
  flex-shrink: 0;
  font-variant-numeric: tabular-nums;
}
.island-task-more {
  font-size: 10px;
  color: rgb(var(--c-text-muted));
  padding: 2px 4px 0;
}
.island-done-group {
  border-top: 1px solid rgba(var(--c-border), 0.05);
  padding-top: 6px;
}
.island-done-head {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 3px 8px;
  font-size: 10px;
  color: rgb(var(--c-text-muted));
  cursor: pointer;
  border-radius: 6px;
  border: none;
  background: transparent;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  width: 100%;
}
.island-done-head:hover {
  background: rgba(255, 255, 255, 0.03);
}
.island-done-chev {
  display: flex;
  align-items: center;
  transition: transform 0.2s;
}
.island-done-chev > svg {
  width: 11px;
  height: 11px;
}
.island-done-chev-open {
  transform: rotate(90deg);
}
.island-done-head-count {
  margin-left: auto;
  font-variant-numeric: tabular-nums;
}
.island-done-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding-top: 4px;
}
.island-done-row-wrap {
  border: 1px solid rgba(var(--c-border), 0.05);
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.015);
  overflow: hidden;
}
.island-done-row {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 4px 10px;
  border: none;
  background: transparent;
  border-radius: 6px;
  opacity: 0.85;
  cursor: default;
  font: inherit;
  text-align: left;
}
.island-done-row-click {
  cursor: pointer;
}
.island-done-row:hover {
  background: rgba(255, 255, 255, 0.03);
}
.island-done-row .d-ico {
  width: 13px;
  height: 13px;
  flex-shrink: 0;
  color: rgb(var(--c-text-muted));
  display: flex;
  align-items: center;
  justify-content: center;
}
.island-done-row .d-ico > svg {
  width: 100%;
  height: 100%;
}
.island-done-row .d-title {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 11px;
  color: rgb(var(--c-text-tertiary));
}
.island-done-row .d-meta {
  font-size: 10px;
  color: rgb(var(--c-text-muted));
  flex-shrink: 0;
  font-variant-numeric: tabular-nums;
}
.island-agg-count {
  font-size: 10px;
  padding: 1px 6px;
  background: rgba(var(--c-primary), 0.15);
  border-radius: 4px;
  color: rgb(var(--c-primary));
  flex-shrink: 0;
  font-variant-numeric: tabular-nums;
}
.island-done-detail {
  border-top: 1px solid rgba(var(--c-border), 0.05);
  background: rgba(0, 0, 0, 0.2);
  padding: 6px 10px 8px 28px;
  max-height: 140px;
  overflow-y: auto;
}
.island-done-detail-text {
  font-size: 11px;
  color: rgb(var(--c-text-secondary));
  line-height: 1.5;
  white-space: pre-wrap;
  word-break: break-word;
}
.island-done-detail-output {
  font-size: 10px;
  color: rgb(var(--c-text-muted));
  font-family: var(--c-font-mono, "SF Mono", "JetBrains Mono", Consolas, monospace);
  line-height: 1.5;
  white-space: pre-wrap;
  word-break: break-word;
  margin-top: 4px;
  max-height: 100px;
  overflow-y: auto;
}
.island-empty {
  padding: 12px 8px;
  text-align: center;
  font-size: 11px;
  color: rgb(var(--c-text-muted));
}
.island-foot {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 8px 0;
  border-top: 1px solid rgba(var(--c-border), 0.05);
  margin-top: 2px;
  font-size: 10px;
  color: rgb(var(--c-text-muted));
}
.island-foot-label {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 4px;
}
.island-foot-label > svg {
  width: 11px;
  height: 11px;
}
.island-water {
  flex: 1;
  height: 3px;
  background: rgba(255, 255, 255, 0.06);
  border-radius: 2px;
  overflow: hidden;
}
.island-water > i {
  display: block;
  height: 100%;
  background: rgb(var(--c-accent-ai));
  border-radius: 2px;
  transition: width 0.4s;
}
.island-water-warn > i {
  background: rgb(var(--c-status-warning));
}
.island-water-num {
  flex-shrink: 0;
  font-variant-numeric: tabular-nums;
}
